(function () {
	'use strict';

	function ready(callback) {
		if (document.readyState === 'loading') {
			document.addEventListener('DOMContentLoaded', callback);
			return;
		}

		callback();
	}

	ready(function () {
		var openBtn = document.querySelector('.mobile-nav-icon');
		var sidebar = document.querySelector('.mobile-sidebar');
		var closeBtn = document.querySelector('.menu-close');
		var mobileNav = document.querySelector('.mobile-nav');

		if (openBtn && sidebar) {
			openBtn.addEventListener('click', function () {
				sidebar.classList.add('mobile-menu-active');
			});
		}

		if (closeBtn && sidebar) {
			closeBtn.addEventListener('click', function () {
				sidebar.classList.remove('mobile-menu-active');
			});
		}

		if (!mobileNav) {
			return;
		}

		mobileNav.querySelectorAll('a').forEach(function (link) {
			if ((link.getAttribute('href') || '') === '#') {
				link.classList.add('hash-nav');
			} else {
				link.classList.remove('hash-nav');
			}
		});

		mobileNav.querySelectorAll('li ul').forEach(function (submenu) {
			var parent = submenu.parentElement;
			if (parent) {
				parent.classList.add('has-sub');
			}
		});

		mobileNav.querySelectorAll('.has-sub').forEach(function (item) {
			if (item.querySelector('.submenu-button')) {
				return;
			}

			var submenuButton = document.createElement('span');
			submenuButton.className = 'submenu-button';
			submenuButton.innerHTML = '<em></em>';
			item.insertBefore(submenuButton, item.firstChild);

			submenuButton.addEventListener('click', function () {
				submenuButton.classList.toggle('submenu-opened');

				var submenu = item.querySelector('ul');
				if (!submenu) {
					return;
				}

				if (submenu.classList.contains('open-sub')) {
					submenu.classList.remove('open-sub');
					submenu.style.display = 'none';
				} else {
					submenu.classList.add('open-sub');
					submenu.style.display = 'block';
				}
			});
		});

		function syncVisibility() {
			if (window.innerWidth > 991) {
				mobileNav.querySelectorAll('ul').forEach(function (submenu) {
					submenu.style.display = '';
				});
				mobileNav.querySelectorAll('ul.sub-menu').forEach(function (submenu) {
					submenu.style.display = 'none';
				});
			}
		}

		syncVisibility();
		window.addEventListener('resize', syncVisibility);
	});
})();
